{"BypassSandbox":true,"CommandLine":"node -e '
const fs = require("fs");
const http = require("http");
const html = fs.readFileSync("frontend/index.html", "utf8");

const links = [...html.matchAll(/<link[^>]+href=["\x27]([^"\x27]+)["\x27]/gi)].map(m => m[1]);
const scripts = [...html.matchAll(/<script[^>]+src=["\x27]([^"\x27]+)["\x27]/gi)].map(m => m[1]);
const allAssets = [...links, ...scripts].filter(u => !u.startsWith("http") && !u.startsWith("//"));

let completed = 0;
let errors = 0;

for (const asset of allAssets) {
  const url = "http://localhost:3001/" + asset.replace(/^\//, "");
  http.get(url, { headers: { "Accept-Encoding": "gzip, deflate, br" } }, (res) => {
    if (res.statusCode !== 200) {
      console.error(`Status ${res.statusCode} for ${url}`);
      errors++;
    }
    completed++;
    if (completed === allAssets.length) {
      console.log(`Verified ${completed} assets via HTTP. Errors: ${errors}`);
    }
  }).on("error", (e) => {
    console.error(`Error fetching ${url}: ${e.message}`);
    errors++;
  });
}
'","WaitMsBeforeAsync":5000,"toolSummary":"Verify assets return 200 OK via HTTP"}
